function b64urlDecode(s){ s=s.replace(/-/g,'+').replace(/_/g,'/'); while(s.length%4) s+='=';
  var bin;
  if(typeof atob!=='undefined'){ bin=atob(s); }
  else { var chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'; var lu={};
    for(var ci=0;ci<chars.length;ci++) lu[chars.charCodeAt(ci)]=ci;
    bin=''; var buf=0,bits=0;
    for(var j=0;j<s.length;j++){ var c=s[j]; if(c==='=') break; var v=lu[c.charCodeAt(0)]; if(v===undefined) continue;
      buf=(buf<<6)|v; bits+=6; if(bits>=8){ bits-=8; bin+=String.fromCharCode((buf>>bits)&0xff); } } }
  try { return decodeURIComponent(escape(bin)); } catch(e){ return bin; } }
function decode(token){ var parts=token.split('.'); if(parts.length!==3) return {error:'JWT 须为 3 段 header.payload.signature'};
  var header=null,payload=null,err=null;
  try{ header=JSON.parse(b64urlDecode(parts[0])); }catch(e){ err='header 解码失败'; }
  try{ payload=JSON.parse(b64urlDecode(parts[1])); }catch(e){ err='payload 解码失败'; }
  return {header:header, payload:payload, signature:parts[2], error:err}; }
var EXPORTS={decode:decode, b64urlDecode:b64urlDecode};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.JwtDecodeForgePure = EXPORTS; }
